package com.elitedarkkaiser.nubialy;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
/** RisingOS-style home content. Every category action is supplied by its native preference. */
public final class SettingsHomeView extends LinearLayout {
 public record Entry(String key,CharSequence title,CharSequence summary,Drawable icon,Runnable open){}
 private final SettingsStyle style;private final java.util.function.BooleanSupplier allowed;private final Ring battery,storage;private final TextView batteryNote;private final Runnable update;
 public SettingsHomeView(Context c,SettingsStyle s,List<List<Entry>> groups,CharSequence user,Runnable profile,Runnable search,java.util.function.BooleanSupplier gate){super(c);style=s;allowed=gate;setOrientation(VERTICAL);setBackgroundColor(s.background());setPadding(dp(12),dp(8),dp(12),dp(8));ScrollView scroll=new ScrollView(c);LinearLayout content=new LinearLayout(c);content.setOrientation(VERTICAL);scroll.addView(content);addView(scroll,new LayoutParams(-1,0,1));
 LinearLayout metrics=new LinearLayout(c);content.addView(metrics);LinearLayout b=box(),st=box();LayoutParams a=new LayoutParams(0,-2,1);a.rightMargin=dp(s.gap());metrics.addView(b,a);metrics.addView(st,new LayoutParams(0,-2,1));b.addView(label("Battery",14,s.summary()));st.addView(label("Storage",14,s.summary()));battery=new Ring(c);storage=new Ring(c);b.addView(battery,new LayoutParams(-1,dp(112)));st.addView(storage,new LayoutParams(-1,dp(112)));batteryNote=label("",12,s.summary());b.addView(batteryNote);TextView disk=label("",12,s.summary());st.addView(disk);Entry batteryRoute=find(groups,"battery"),storageRoute=find(groups,"storage");if(batteryRoute!=null)b.setOnClickListener(v->{if(gate.getAsBoolean())batteryRoute.open().run();});if(storageRoute!=null)st.setOnClickListener(v->{if(gate.getAsBoolean())storageRoute.open().run();});b.setContentDescription("Battery");st.setContentDescription("Storage");
 LinearLayout account=box();LayoutParams gap=new LayoutParams(-1,-2);gap.topMargin=dp(s.gap());content.addView(account,gap);TextView name=label("◉   "+user,16,s.title());account.addView(name);account.setMinimumHeight(dp(56));account.setGravity(Gravity.CENTER_VERTICAL);account.setOnClickListener(v->{if(gate.getAsBoolean())profile.run();});
 for(List<Entry> group:groups){LinearLayout card=box();LayoutParams cp=new LayoutParams(-1,-2);cp.topMargin=dp(s.gap());content.addView(card,cp);for(int n=0;n<group.size();n++){Entry e=group.get(n);LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setMinimumHeight(dp(s.rowHeight()));row.setPadding(dp(4),dp(5),dp(4),dp(5));ImageView icon=new ImageView(c);GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor((s.accent()&0xffffff)|0x44000000);icon.setBackground(circle);Drawable d=e.icon();if(d!=null){d=d.getConstantState()==null?d:d.getConstantState().newDrawable(c.getResources()).mutate();icon.setImageDrawable(d);}icon.setPadding(dp(8),dp(8),dp(8),dp(8));int size=dp(40*s.iconScale()/100);row.addView(icon,new LayoutParams(size,size));LinearLayout words=new LinearLayout(c);words.setOrientation(VERTICAL);words.setPadding(dp(14),0,0,0);TextView title=label(e.title(),16,s.title());words.addView(title);if(e.summary()!=null&&e.summary().length()>0){TextView sub=label(e.summary(),13,s.summary());sub.setMaxLines(3);words.addView(sub);}row.addView(words,new LayoutParams(0,-2,1));row.setFocusable(true);row.setClickable(true);row.setContentDescription(e.title());row.setOnClickListener(v->{if(gate.getAsBoolean())e.open().run();});card.addView(row,new LayoutParams(-1,-2));if(n<group.size()-1){View line=new View(c);line.setBackgroundColor((s.summary()&0xffffff)|0x22000000);card.addView(line,new LayoutParams(-1,dp(1)));}}}
 TextView query=label("⌕    Search settings",16,s.summary());query.setGravity(Gravity.CENTER_VERTICAL);query.setPadding(dp(18),0,dp(18),0);query.setBackground(new SettingsCardDrawable(s,getResources().getDisplayMetrics().density,gate));query.setMinimumHeight(dp(56));query.setFocusable(true);query.setClickable(true);query.setOnClickListener(v->{if(gate.getAsBoolean())search.run();});LayoutParams qp=new LayoutParams(-1,-2);qp.topMargin=dp(10);addView(query,qp);
 update=()->{Intent i=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int level=i==null?-1:i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=i==null?100:i.getIntExtra(BatteryManager.EXTRA_SCALE,100);int pct=level<0||scale<=0?-1:level*100/scale;boolean charging=i!=null&&i.getIntExtra(BatteryManager.EXTRA_PLUGGED,0)!=0;int temp=i==null?0:i.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,0);battery.set(pct<0?0:pct/100f,pct<0?"—":pct+"%",temp==0?"":String.format(java.util.Locale.getDefault(),"%.1f°C",temp/10f));batteryNote.setText(charging?"Charging":"Discharging");StatFs fs=new StatFs(Environment.getDataDirectory().getPath());long total=fs.getTotalBytes(),free=fs.getAvailableBytes();storage.set(total==0?0:1-free/(float)total,String.format(java.util.Locale.getDefault(),"%.0f GB",free/1e9),"Available");disk.setText(String.format(java.util.Locale.getDefault(),"%.1f / %.0f GB used",(total-free)/1e9,total/1e9));};update.run();}
 public void refresh(){update.run();}
 private static Entry find(List<List<Entry>> groups,String needle){for(List<Entry> g:groups)for(Entry e:g)if(e.key().toLowerCase(java.util.Locale.ROOT).contains(needle))return e;return null;}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private TextView label(CharSequence text,int size,int color){TextView t=new TextView(getContext());t.setText(text);t.setTextSize(size*style.textScale()/100f);t.setTextColor(color);t.setPadding(0,dp(3),0,dp(3));return t;}
 private LinearLayout box(){LinearLayout b=new LinearLayout(getContext());b.setOrientation(VERTICAL);b.setPadding(dp(14),dp(10),dp(14),dp(10));b.setBackground(new SettingsCardDrawable(style,getResources().getDisplayMetrics().density,allowed));return b;}
 private final class Ring extends View {float fraction;String main="",sub="";Ring(Context c){super(c);}void set(float f,String m,String s){fraction=Math.max(0,Math.min(1,f));main=m;sub=s;setContentDescription(m+" "+s);invalidate();}@Override protected void onDraw(Canvas canvas){if(!allowed.getAsBoolean())return;Paint p=new Paint(3);float size=Math.min(getWidth(),getHeight())-dp(14),x=getWidth()/2f,y=getHeight()/2f;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(7));p.setStrokeCap(Paint.Cap.ROUND);RectF r=new RectF(x-size/2,y-size/2,x+size/2,y+size/2);p.setColor((style.accent()&0xffffff)|0x22000000);canvas.drawArc(r,-90,360,false,p);p.setColor(style.accent());canvas.drawArc(r,-90,360*fraction,false,p);p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(16));p.setColor(style.title());canvas.drawText(main,x,y,p);p.setTextSize(dp(11));p.setColor(style.summary());canvas.drawText(sub,x,y+dp(18),p);}}
}
